import itertools
import random

def max_edges_subgraph(adj, k):
    max_e = 0
    nodes = list(range(len(adj)))
    for subset in itertools.combinations(nodes, k):
        e = 0
        for i in range(len(subset)):
            for j in range(i + 1, len(subset)):
                if adj[subset[i]][subset[j]]:
                    e += 1
        if e > max_e:
            max_e = e
    return max_e

def get_max_e_for_random_graph(v, e, k):
    adj = [[False]*v for _ in range(v)]
    edges = []
    all_edges = list(itertools.combinations(range(v), 2))
    sampled_edges = random.sample(all_edges, e)
    for u, w in sampled_edges:
        adj[u][w] = adj[w][u] = True
    return max_edges_subgraph(adj, k)

